#!/usr/bin/env bash
set -euo pipefail
command -v python3 >/dev/null
command -v install >/dev/null
install -d /opt/memguard
# Fixed project-owned worker bytes, never fetched or supplied by an incident.
install -m 0444 <(printf '%s' '' | base64 --decode) /opt/memguard/replay.py
printf '%s\n' 'MemGuard replay worker installed.'
